// ---------- Parse the GitHub Trending page ----------
function stripTags(s) { return s.replace(/<[^>]*>/g, ''); }
function decodeEntities(s) {
  return String(s)
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&');
}
function txt(s) { return decodeEntities(stripTags(String(s || ''))).replace(/\s+/g, ' ').trim(); }
function toInt(s) { const n = String(s || '').replace(/[^\d]/g, ''); return n ? parseInt(n, 10) : 0; }
function escRe(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

const cfg = $('1. Setup').first().json;
const first = $input.first().json || {};
const html = first.data ?? first.body ?? first.html ?? '';

const blocks = String(html).split('<article class="Box-row">').slice(1);
const repos = [];
for (const raw of blocks) {
  const block = raw.split('</article>')[0].replace(/<svg[\s\S]*?<\/svg>/g, ' ');
  const hrefMatch = block.match(/<h2[^>]*>[\s\S]*?<a[^>]*href="\/([^"]+)"/);
  if (!hrefMatch) continue;
  const fullName = decodeURIComponent(hrefMatch[1]);
  const parts = fullName.split('/');
  if (parts.length !== 2) continue;

  const descMatch = block.match(/<p class="col-9[^"]*">([\s\S]*?)<\/p>/);
  const langMatch = block.match(/itemprop="programmingLanguage">([^<]+)</);
  const starMatch = block.match(new RegExp('href="/' + escRe(fullName) + '/stargazers"[^>]*>([\\s\\S]*?)</a>'));
  const forkMatch = block.match(new RegExp('href="/' + escRe(fullName) + '/forks"[^>]*>([\\s\\S]*?)</a>'));
  const todayMatch = block.match(/([\d,]+)\s+stars?\s+today/i);
  const builtBy = Array.from(block.matchAll(/alt="@([^"]+)"/g)).map((m) => m[1]).slice(0, 5);

  repos.push({
    full_name: fullName,
    owner: parts[0],
    name: parts[1],
    url: 'https://github.com/' + fullName,
    description: txt(descMatch ? descMatch[1] : ''),
    language: langMatch ? txt(langMatch[1]) : '',
    stars: toInt(starMatch ? starMatch[1] : ''),
    forks: toInt(forkMatch ? forkMatch[1] : ''),
    stars_today: toInt(todayMatch ? todayMatch[1] : ''),
    built_by: builtBy,
  });
}

if (!repos.length) {
  throw new Error('Failed to parse any repository from the GitHub Trending page; check the network / page structure may have changed');
}

const keep = Number(cfg.repoCount || 10);
return repos.slice(0, keep > 0 ? keep : 10).map((r) => ({ json: r }));

// ---------- Fetch each project's README and merge with trend data ----------
// Note: this uses the Code node's built-in this.helpers.httpRequest to fetch one by one;
// a single project failing (404 / timeout) won't break the overall flow.
function cleanMarkdown(md, limit) {
  let s = String(md || '');
  s = s.replace(/<!--[\s\S]*?-->/g, ' ');
  s = s.replace(/```[\s\S]*?```/g, ' ');          // strip code blocks
  s = s.replace(/`[^`\n]*`/g, ' ');
  s = s.replace(/!\[[^\]]*\]\([^)]*\)/g, ' ');    // images
  s = s.replace(/\[([^\]]*)\]\([^)]*\)/g, '$1');  // links: keep text only
  s = s.replace(/<img[^>]*>/gi, ' ').replace(/<[^>]+>/g, ' ');
  s = s.replace(/^\s*#{1,6}\s*/gm, '');
  s = s.replace(/^\s*[-*+>]\s+/gm, '');
  s = s.replace(/[ \t]+/g, ' ');
  s = s.replace(/\n{2,}/g, '\n');
  s = s.trim();
  return s.length > limit ? s.slice(0, limit) + ' …' : s;
}

const cfg = $('1. Setup').first().json;
const fetchReadme = cfg.fetchReadme !== false;
const limit = Number(cfg.readmeChars || 3000);
const repos = $input.all().map((i) => i.json);

const out = [];
for (const r of repos) {
  let readme = '';
  let readmeOk = false;
  if (fetchReadme) {
    for (const ref of ['HEAD', 'main', 'master']) {
      try {
        const res = await this.helpers.httpRequest({
          method: 'GET',
          url: 'https://raw.githubusercontent.com/' + r.full_name + '/' + ref + '/README.md',
          headers: { 'User-Agent': 'n8n-github-trending-bot' },
          timeout: 15000,
        });
        if (res && typeof res === 'string' && res.length > 40) {
          readme = cleanMarkdown(res, limit);
          readmeOk = true;
          break;
        }
      } catch (e) {
        // try the next ref
      }
    }
  }
  out.push({ json: Object.assign({}, r, { readme, readme_ok: readmeOk }) });
}

return out;

// ---------- Build the AI analysis request body ----------
const cfg = $('1. Setup').first().json;
const repos = $input.all().map((i) => i.json);
const today = new Date().toISOString().slice(0, 10);

// Only feed the model the fields it needs, to keep token usage under control
const slim = repos.map((r) => ({
  full_name: r.full_name,
  url: r.url,
  language: r.language,
  stars: r.stars,
  forks: r.forks,
  stars_today: r.stars_today,
  description: r.description,
  readme: r.readme || (r.readme_ok ? '' : '(README unavailable)'),
}));

const systemPrompt = [
  'You are a senior open-source trend analyst writing a daily briefing for developers.',
  'You will receive today\'s GitHub Trending repositories with README excerpts.',
  'Write in English. Be concrete and opinionated; no marketing fluff, no em dash, no generic filler.',
  'Ground every claim strictly in the provided data. If the README is thin, say what is uncertain instead of inventing details.',
  'Return ONLY valid JSON matching the required schema. No code fences, no extra commentary.',
].join(' ');

const schemaHint = JSON.stringify({
  title: 'Issue title, English, within 20 words',
  summary: 'Overall overview, 3-5 sentences, pointing out the overall trend direction',
  highlights: ['3 most notable judgments for this issue, one sentence each'],
  repos: [{
    full_name: 'owner/repo (must match the input exactly)',
    one_liner: 'One sentence explaining what problem it solves',
    why_hot: 'Why it is trending today, 2-3 sentences, be specific',
    use_case: 'Who it is for and how to use it, 1-2 sentences',
    tags: ['2-4 tags in English or Chinese'],
    score: 88,
  }],
}, null, 2);

const userPrompt = [
  'Date: ' + today,
  'Total ' + slim.length + ' projects, sorted by today\'s star growth.',
  '',
  'Please output the following JSON structure:',
  schemaHint,
  '',
  'Project data:',
  JSON.stringify(slim, null, 2),
].join('\n');

const body = {
  model: cfg.aiModel,
  temperature: 0.4,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt },
  ],
};
if (cfg.aiMaxTokens) body.max_tokens = Number(cfg.aiMaxTokens);
if (cfg.aiJsonMode !== false) body.response_format = { type: 'json_object' };

return [{ json: { apiUrl: cfg.aiApiUrl, requestBody: body, date: today, repoCount: repos.length } }];

const CSS = "*,*::before,*::after{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;background:#f5f6f8;color:#1a1d21;font:16px/1.65 -apple-system,BlinkMacSystemFont,\"Segoe UI\",\"PingFang SC\",\"Hiragino Sans GB\",\"Microsoft YaHei\",Roboto,Helvetica,Arial,sans-serif}\nmain{max-width:860px;margin:0 auto;padding:32px 20px 64px}\na{color:#4f46e5;text-decoration:none}\na:hover{text-decoration:underline}\n.hero{margin-bottom:24px}\n.kicker{font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#4f46e5}\n.hero h1{margin:8px 0 4px;font-size:30px;line-height:1.25;letter-spacing:-.01em}\n.date{color:#5b6470;font-size:14px}\n.stats{display:flex;gap:12px;margin-top:18px;flex-wrap:wrap}\n.stats>div{flex:1 1 140px;background:#fff;border:1px solid #e4e7ec;border-radius:12px;padding:12px 14px}\n.stats b{display:block;font-size:22px;line-height:1.2}\n.stats span{font-size:12px;color:#5b6470}\n.panel{background:#fff;border:1px solid #e4e7ec;border-radius:14px;padding:18px 20px;margin-bottom:24px}\n.panel h2{margin:0 0 10px;font-size:15px;color:#5b6470;font-weight:700;letter-spacing:.02em}\n.summary p{margin:0;color:#25292f}\n.panel ul{margin:0;padding-left:20px}\n.panel li{margin:6px 0}\n.list{display:grid;gap:16px}\n.card{background:#fff;border:1px solid #e4e7ec;border-radius:14px;padding:18px 20px}\n.card-head{display:flex;align-items:baseline;gap:12px}\n.rank{flex:none;width:26px;height:26px;border-radius:8px;background:#eef0f4;color:#5b6470;font-size:13px;font-weight:700;display:flex;align-items:center;justify-content:center}\n.card-title{flex:1;display:flex;align-items:baseline;gap:10px;flex-wrap:wrap}\n.card-title a{font-size:18px;font-weight:700;letter-spacing:-.01em;word-break:break-all}\n.score{font-size:12px;font-weight:700;color:#b45309;background:#fef3c7;border-radius:999px;padding:2px 8px}\n.meta{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0 12px}\n.lang,.chip{font-size:12px;color:#3d4450;background:#f2f4f7;border:1px solid #e4e7ec;border-radius:999px;padding:2px 10px;display:inline-flex;align-items:center;gap:5px}\n.lang i{width:9px;height:9px;border-radius:50%;display:inline-block}\n.chip.accent{background:#eef2ff;border-color:#dfe4ff;color:#4338ca;font-weight:600}\n.oneliner{margin:0 0 8px;font-size:16px;font-weight:600;line-height:1.5}\n.desc{margin:0 0 12px;color:#5b6470;font-size:14px}\n.blk{margin:10px 0 0}\n.lbl{display:inline-block;font-size:11px;font-weight:700;letter-spacing:.06em;color:#5b6470;background:#f2f4f7;border-radius:6px;padding:2px 7px;margin-bottom:5px}\n.blk p{margin:0;font-size:15px;color:#25292f}\n.tags{margin-top:12px;display:flex;flex-wrap:wrap;gap:6px}\n.tag{font-size:12px;color:#4338ca;background:#eef2ff;border-radius:6px;padding:2px 8px}\nfooter{margin-top:36px;text-align:center;color:#8b94a3;font-size:12px}\n@media(max-width:520px){main{padding:20px 14px 48px}.hero h1{font-size:24px}.card{padding:16px}}\n";
// ---------- Parse AI output + render HTML report ----------
function esc(s) {
  return String(s === undefined || s === null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}
function num(n) {
  const v = Number(n);
  if (!isFinite(v) || v <= 0) return '0';
  return v.toLocaleString('en-US');
}
function cleanMdInline(s) {
  return esc(String(s || '')).replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
}

const LANG_COLORS = {
  JavaScript: '#f1e05a', TypeScript: '#3178c6', Python: '#3572A5', Java: '#b07219',
  Go: '#00ADD8', Rust: '#dea584', 'C++': '#f34b7d', C: '#555555', 'C#': '#178600',
  Ruby: '#701516', PHP: '#4F5D95', Swift: '#F05138', Kotlin: '#A97BFF', Shell: '#89e051',
  HTML: '#e34c26', CSS: '#563d7c', Vue: '#41b883', Svelte: '#ff3e00', Dart: '#00B4AB',
  Lua: '#000080', Zig: '#ec915c', Jupyter: '#DA5B0B', 'Jupyter Notebook': '#DA5B0B',
};
function langColor(l) { return LANG_COLORS[l] || '#8b949e'; }

// --- 1. Recover trend data (raw facts) ---
const repos = $('4. Fetch & Merge READMEs').all().map((i) => i.json);
const cfg = $('1. Setup').first().json;
const date = new Date().toISOString().slice(0, 10);
// A date-based filename is fine; htmlhoster now auto-detects the entry page from any HTML filename (after the v0.5.x entryUrl fix).
const entryFileName = `github-trending-${date}.html`;

// --- 2. Parse AI output; fall back to no-AI mode on failure ---
let ai = null;
let aiRaw = '';
try {
  const resp = $input.first().json || {};
  aiRaw = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '';
  if (aiRaw) {
    let s = String(aiRaw).trim();
    s = s.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
    const a = s.indexOf('{');
    const b = s.lastIndexOf('}');
    if (a !== -1 && b > a) s = s.slice(a, b + 1);
    ai = JSON.parse(s);
  }
} catch (e) {
  ai = null;
}
const aiUsed = !!(ai && Array.isArray(ai.repos) && ai.repos.length);

const aiByRepo = {};
if (aiUsed) {
  for (const r of ai.repos) {
    if (r && r.full_name) aiByRepo[String(r.full_name).toLowerCase()] = r;
  }
}

// --- 3. Merge ---
const items = repos.map((r, idx) => {
  const a = aiByRepo[String(r.full_name).toLowerCase()] || {};
  return {
    rank: idx + 1,
    full_name: r.full_name,
    url: r.url,
    language: r.language || '—',
    stars: r.stars,
    forks: r.forks,
    stars_today: r.stars_today,
    built_by: r.built_by || [],
    description: r.description,
    one_liner: a.one_liner || r.description || '(AI analysis unavailable)',
    why_hot: a.why_hot || '',
    use_case: a.use_case || '',
    tags: Array.isArray(a.tags) ? a.tags.filter(Boolean).slice(0, 4) : [],
    score: isFinite(Number(a.score)) && Number(a.score) > 0 ? Math.round(Number(a.score)) : null,
  };
});

const title = (ai && ai.title) ? String(ai.title) : 'GitHub Daily Trending Brief';
const summary = (ai && ai.summary) ? String(ai.summary)
  : 'A total of ' + items.length + ' projects made today\'s GitHub Trending. No AI analysis was returned, so the raw list is shown below.';
const highlights = (ai && Array.isArray(ai.highlights)) ? ai.highlights.filter(Boolean).slice(0, 5) : [];
const totalToday = items.reduce((s, r) => s + (r.stars_today || 0), 0);

// --- 4. Render HTML ---
const cardHtml = items.map((r) => {
  const tagsHtml = r.tags.length
    ? '<div class="tags">' + r.tags.map((t) => '<span class="tag">' + esc(t) + '</span>').join('') + '</div>'
    : '';
  const whyHtml = r.why_hot ? '<div class="blk"><span class="lbl">Why trending</span><p>' + cleanMdInline(r.why_hot) + '</p></div>' : '';
  const useHtml = r.use_case ? '<div class="blk"><span class="lbl">Who it\'s for</span><p>' + cleanMdInline(r.use_case) + '</p></div>' : '';
  const scoreHtml = r.score !== null ? '<span class="score" title="Editor\'s pick score">' + r.score + '</span>' : '';
  const descHtml = r.description ? '<p class="desc">' + esc(r.description) + '</p>' : '';

  return [
    '<article class="card">',
    '<div class="card-head">',
    '<span class="rank">' + r.rank + '</span>',
    '<div class="card-title">',
    '<a href="' + esc(r.url) + '" target="_blank" rel="noopener">' + esc(r.full_name) + '</a>',
    scoreHtml,
    '</div>',
    '</div>',
    '<div class="meta">',
    r.language !== '—' ? '<span class="lang"><i style="background:' + langColor(r.language) + '"></i>' + esc(r.language) + '</span>' : '',
    '<span class="chip">★ ' + num(r.stars) + '</span>',
    '<span class="chip accent">Today +' + num(r.stars_today) + '</span>',
    '<span class="chip">⑂ ' + num(r.forks) + '</span>',
    '</div>',
    '<p class="oneliner">' + cleanMdInline(r.one_liner) + '</p>',
    descHtml,
    whyHtml,
    useHtml,
    tagsHtml,
    '</article>',
  ].join('\n');
}).join('\n');

const highlightHtml = highlights.length
  ? '<section class="panel"><h2>Highlights</h2><ul>' +
    highlights.map((h) => '<li>' + cleanMdInline(h) + '</li>').join('') +
    '</ul></section>'
  : '';

const html = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n' +
  '<meta name="viewport" content="width=device-width, initial-scale=1">\n' +
  '<title>' + esc(title) + ' · GitHub Daily Trending</title>\n' +
  '<meta name="description" content="GitHub Daily Trending AI brief · ' + date + '">\n' +
  '<style>' + CSS + '</style>\n</head>\n<body>\n<main>\n' +
  '<header class="hero">' +
  '<div class="kicker">GitHub Trending · Daily</div>' +
  '<h1>' + esc(title) + '</h1>' +
  '<div class="date">' + date + '</div>' +
  '<div class="stats">' +
  '<div><b>' + items.length + '</b><span>Trending projects</span></div>' +
  '<div><b>+' + num(totalToday) + '</b><span>Stars gained today</span></div>' +
  '<div><b>' + (aiUsed ? 'AI insights' : 'Raw data') + '</b><span>Content mode</span></div>' +
  '</div>' +
  '</header>\n' +
  '<section class="panel summary"><h2>Overview</h2><p>' + cleanMdInline(summary) + '</p></section>\n' +
  highlightHtml + '\n' +
  '<section class="list">' + cardHtml + '</section>\n' +
  '<footer>This page was auto-generated by n8n and hosted on HTML Hoster · Source: GitHub Trending (daily)</footer>\n' +
  '</main>\n</body>\n</html>';

return [{
  json: {
    date,
    title,
    summary,
    highlights,
    top: items.slice(0, 3).map((r) => ({ full_name: r.full_name, url: r.url, one_liner: r.one_liner })),
    repoCount: items.length,
    totalToday,
    aiUsed,
  },
  binary: {
    index_html: {
      data: Buffer.from(html, 'utf8').toString('base64'),
      mimeType: 'text/html; charset=utf-8',
      fileName: entryFileName,
    },
  },
  // Pass the filename through so the upload node's `paths` form field can reference it (must match the binary fileName)
  entryFileName,
}];

// ---------- Build DingTalk / Feishu push messages (with signing) ----------
// Pure-JS HMAC-SHA256 to avoid depending on the n8n Code node's crypto allowlist
const HMAC_K = [0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2];

function sha256(msgBytes) {
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  const ml = msgBytes.length;
  const withPad = new Uint8Array((((ml + 8) >> 6) + 1) << 6);
  withPad.set(msgBytes);
  withPad[ml] = 0x80;
  const bitLen = ml * 8;
  const dv = new DataView(withPad.buffer);
  dv.setUint32(withPad.length - 4, bitLen >>> 0, false);
  dv.setUint32(withPad.length - 8, Math.floor(bitLen / 4294967296), false);
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const w = new Uint32Array(64);
  for (let off = 0; off < withPad.length; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = dv.getUint32(off + i * 4, false);
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + HMAC_K[i] + w[i]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0;
      d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  const out = new Uint8Array(32);
  const odv = new DataView(out.buffer);
  for (let i = 0; i < 8; i++) odv.setUint32(i * 4, H[i], false);
  return out;
}
function toBytes(str) { return new TextEncoder().encode(str); }
function toBase64(bytes) { let bin = ''; for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]); return btoa(bin); }
function hmacSha256Base64(keyStr, msgStr) {
  let key = toBytes(keyStr);
  const blockSize = 64;
  if (key.length > blockSize) key = sha256(key);
  const ipad = new Uint8Array(blockSize);
  const opad = new Uint8Array(blockSize);
  for (let i = 0; i < blockSize; i++) {
    ipad[i] = (key[i] || 0) ^ 0x36;
    opad[i] = (key[i] || 0) ^ 0x5c;
  }
  const msgBytes = toBytes(msgStr);
  const inner = new Uint8Array(blockSize + msgBytes.length);
  inner.set(ipad); inner.set(msgBytes, blockSize);
  const innerHash = sha256(inner);
  const outer = new Uint8Array(blockSize + 32);
  outer.set(opad); outer.set(innerHash, blockSize);
  return toBase64(sha256(outer));
}

const cfg = $('1. Setup').first().json;
const meta = $('7. Render HTML').first().json;
const up = $input.first().json || {};

const pageUrl = up.entryUrl || (Array.isArray(up.urls) && up.urls[0]) || '';
if (!pageUrl) {
  throw new Error('htmlhoster upload did not return entryUrl; push aborted. Response: ' + JSON.stringify(up));
}

const date = meta.date;
const title = meta.title || 'GitHub Daily Trending';
const head = 'GitHub Daily Trending · ' + date;
const topLines = (meta.top || []).map((t, i) =>
  (i + 1) + '. [' + t.full_name + '](' + t.url + ') — ' + String(t.one_liner || '').slice(0, 80)
).join('\n');

const out = [];

// ---------- DingTalk ----------
if (cfg.dingtalkEnabled && String(cfg.dingtalkWebhook || '').trim()) {
  let url = String(cfg.dingtalkWebhook).trim();
  const secret = String(cfg.dingtalkSecret || '').trim();
  if (secret) {
    const ts = Date.now().toString();
    const sign = hmacSha256Base64(secret, ts + '\n' + secret);
    url += (url.indexOf('?') === -1 ? '?' : '&') + 'timestamp=' + ts + '&sign=' + encodeURIComponent(sign);
  }
  const text = [
    '### ' + head,
    '',
    '**' + title + '**',
    '',
    String(meta.summary || '').slice(0, 300),
    '',
    topLines,
    '',
    '[View full report](' + pageUrl + ')',
  ].join('\n');
  out.push({
    json: {
      channel: 'dingtalk',
      url,
      payload: { msgtype: 'markdown', markdown: { title: head, text } },
    },
  });
}

// ---------- Feishu ----------
if (cfg.feishuEnabled && String(cfg.feishuWebhook || '').trim()) {
  const payload = {
    msg_type: 'interactive',
    card: {
      config: { wide_screen_mode: true },
      header: { template: 'indigo', title: { tag: 'plain_text', content: head } },
      elements: [
        { tag: 'div', text: { tag: 'lark_md', content: '**' + title + '**\n' + String(meta.summary || '').slice(0, 400) } },
        { tag: 'hr' },
        { tag: 'div', text: { tag: 'lark_md', content: '**Top Projects**\n' + topLines } },
        {
          tag: 'action',
          actions: [{ tag: 'button', text: { tag: 'plain_text', content: 'View Full Report' }, url: pageUrl, type: 'primary' }],
        },
      ],
    },
  };
  const secret = String(cfg.feishuSecret || '').trim();
  if (secret) {
    const ts = Math.floor(Date.now() / 1000).toString();
    payload.timestamp = ts;
    payload.sign = hmacSha256Base64(ts + '\n' + secret, '');
  }
  out.push({ json: { channel: 'feishu', url: String(cfg.feishuWebhook).trim(), payload } });
}

// If neither channel is enabled, return an empty array so the downstream push node does nothing
return out;
